<?php
namespace App\Models\FinancialV2;
use DomainException;use Illuminate\Database\Eloquent\Relations\HasMany;
final class AccountingDateCorrectionBatch extends FinancialV2Model{protected $table='financial_v2_accounting_date_correction_batches';protected $casts=['target_accounting_date'=>'date','batch_snapshot'=>'array','batch_blockers'=>'array','net_effect'=>'decimal:2','submitted_at'=>'datetime','approved_at'=>'datetime','cancelled_at'=>'datetime'];protected static function booted():void{static::creating(fn()=>throw new DomainException('Batch hanya dibuat service canonical.'));static::updating(fn()=>throw new DomainException('Lifecycle batch hanya diubah service canonical.'));static::deleting(fn()=>throw new DomainException('Batch disimpan permanen.'));}public function items():HasMany{return$this->hasMany(AccountingDateCorrectionBatchItem::class,'batch_id')->orderBy('item_no');}public function approvals():HasMany{return$this->hasMany(AccountingDateCorrectionBatchApproval::class,'batch_id')->orderBy('decided_at')->orderBy('id');}}
